export async function listTools() {
  return [
    {
      name: 'ticket_create',
      description: 'Create a support ticket with a title, description, and optional priority.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Short title of the ticket.' },
          description: { type: 'string', description: 'Detailed description of the issue.' },
          priority: { type: 'string', enum: ['low', 'normal', 'high'], description: 'Ticket priority. Defaults to normal.' },
        },
        required: ['title', 'description'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool: ${name}`);
  }
  return createTicket(args);
}

function createTicket(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const { title, description, priority } = args;

  if (typeof title !== 'string' || title.trim() === '') {
    throw new Error('Invalid arguments: title must be a non-empty string');
  }
  if (typeof description !== 'string' || description.trim() === '') {
    throw new Error('Invalid arguments: description must be a non-empty string');
  }
  if (priority !== undefined) {
    if (typeof priority !== 'string' || !['low', 'normal', 'high'].includes(priority)) {
      throw new Error('Invalid arguments: priority must be one of low, normal, high');
    }
  }

  const id = `t${nextId++}`;
  const finalPriority = priority !== undefined ? priority : 'normal';

  return {
    content: [
      {
        type: 'text',
        text: `Created ticket ${id}: ${title} (priority: ${finalPriority})`,
      },
    ],
  };
}
"}

